import primitive_api as api

def short(x, n=300):
    s = str(x)
    return s[:n] + ("..." if len(s) > n else "")

def ctx_edges(line, keep=("INSIDE", "HOLDS_RH", "HOLDS_LH", "ON", "FACING")):
    ex = api.explain_action_preconditions(line)
    crs = ex.get("current_relevant_state", {}) or {}
    eds = [e for e in crs.get("edges", []) if e["relation"] in keep]
    return ex.get("valid_action"), short(ex.get("error"), 150), eds

for line in ["[GRAB] <phone> (71)", "[WALK] <phone> (1000)", "[WALK] <phone> (2045)", "[WALK] <home_office> (241)"]:
    v, err, eds = ctx_edges(line)
    print(line, "->", v, err, eds[:12])

rooms = api.query_symbolic_state(scope="Rooms")
print("ROOMS:", [(n["id"], n["class_name"]) for n in rooms.get("nodes", [])])
print("SUCCESS:", api.check_activity_success())
